examples.code:
PRAGMA foreign_keys = ON;
CREATE TABLE Customer (customer_id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE Orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, FOREIGN KEY (customer_id) REFERENCES Customer(customer_id));

CREATE TABLE Student (student_id INTEGER PRIMARY KEY, student_name TEXT NOT NULL);
CREATE TABLE Course (course_id INTEGER PRIMARY KEY, course_title TEXT NOT NULL);
CREATE TABLE Enrollment (
  student_id INTEGER NOT NULL,
  course_id INTEGER NOT NULL,
  enrolled_on TEXT NOT NULL,
  PRIMARY KEY (student_id, course_id),
  FOREIGN KEY (student_id) REFERENCES Student(student_id) ON UPDATE CASCADE ON DELETE CASCADE,
  FOREIGN KEY (course_id) REFERENCES Course(course_id) ON UPDATE CASCADE ON DELETE RESTRICT
);

